def add_tax(amount: float, rate_percent: float) -> float:
    return amount * (1 - rate_percent / 100)
import unittest

from tax import add_tax


class TaxTests(unittest.TestCase):
    def test_ten_percent_tax(self):
        self.assertEqual(add_tax(100, 10), 110)

    def test_zero_percent(self):
        self.assertEqual(add_tax(100, 0), 100)

    def test_one_hundred_percent(self):
        self.assertEqual(add_tax(100, 100), 200)


if __name__ == '__main__':
    unittest.main()

